// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint64 t1, uint64 t2, address actor) public {
        vm.assume(actor != address(c) && actor != address(this));
        t1 = bound(t1, 1, type(uint64).max / 2); // strictly after genesis timestamp 0
        t2 = bound(t2, 1, t1);                   // t2 <= t1, NOT strictly greater

        vm.deal(actor, 20 ether);

        // First deposit at time t1 succeeds on both versions (t1 > 0 = pastBlockTime).
        vm.warp(t1);
        vm.prank(actor);
        address(c).call{value: 10 ether}("");

        // Second deposit at time t2 <= t1 must revert on the reference contract.
        vm.warp(t2);
        vm.prank(actor);
        bool ok;
        try c.fallbackCall{value: 10 ether}() { ok = true; }
        catch { ok = false; }

        // For every admissible (t1 > 0, t2 <= t1): the second call must fail.
        // Reference: reverts (t2 > t1 is false, and t2 == t1 fails too).
        // Mutant: succeeds when t2 < t1 (t2 < t1 passes its inverted check).
        assertTrue(!ok);
    }
}

// Helper shim so the payable fallback can be invoked via try/catch (fallback cannot
// be called as c.fallback() in Solidity source).
contract C_shim {
    C target;
    constructor(C _t) { target = _t; }
    function fallbackCall() external payable {
        (bool s,) = address(target).call{value: msg.value}("");
        require(s, "call failed");
    }
    receive() external payable {}
}

