import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(ts > block.number + 1); // timestamp strictly greater than any possible block number here
        vm.deal(actor, 10 ether);
        vm.warp(ts); // set the block timestamp for the upcoming call
        vm.prank(actor);
        c.fallback{value: 10 ether}();
        // General rule: pastBlockTime records the block.timestamp of the last call.
        assertTrue(c.pastBlockTime() == ts);
    }
}

