pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint64 lastTs;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 n, uint64 ts, address actor) public {
        vm.assume(actor.code.length == 0);
        vm.assume(ts > lastTs);
        lastTs = ts;
        vm.warp(ts);
        vm.roll(n);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok);
        // Rule: if block.number % 15 != 0, C never pays out, so its balance stays 10 ether.
        assertTrue(n % 15 == 0 || address(c).balance == 10 ether);
    }
}

