// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNum, uint64 ts, address actor) public {
        // admissible domain: block number where the payout branch must NOT fire
        blockNum = bound(blockNum, 0, type(uint64).max - 1);
        vm.assume(blockNum % 15 != 0);
        vm.assume(ts > 1);

        vm.roll(blockNum);
        // timestamp strictly greater than any previously recorded pastBlockTime
        vm.warp(ts);

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        bool ok;
        try c.fallback{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: whenever the call succeeds with 10 ether at a block
        // number not divisible by 15, the reference keeps its full balance.
        assertTrue(!ok || address(c).balance == 10 ether);
    }
}

