pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }
    function testFuzz_property(uint256 blockNum) public {
        blockNum = bound(blockNum, 0, type(uint256).max - 1);
        vm.roll(blockNum);
        uint balBefore = address(c).balance;
        bool ok;
        (bool s, ) = address(c).call{value: 10 ether}("");
        ok = s;
        assertTrue(!(ok && blockNum % 15 != 0 && address(c).balance != balBefore), "balance must not change on successful call when blockNum % 15 != 0");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 n, uint256 ts) public {
        // Admissible domain: any block number; timestamp must advance past the initial pastBlockTime (0).
        ts = bound(ts, 1, type(uint256).max / 2);
        vm.roll(n);
        vm.warp(ts);

        // Deploy a re-entrant attacker: on receiving the payout it immediately
        // deposits 10 ether again into c within the same block/transaction.
        Attacker a = new Attacker(c);
        vm.deal(address(a), 20 ether);

        // Drive c through its fallback via the attacker.
        a.attack();

        // General rule: if the jackpot block is hit, the payout cannot be
        // re-entered; the contract must end holding exactly its original
        // 10 ether seed (either no payout happened, or the re-entrant
        // follow-up reverted the whole transaction). The mutant lets the
        // attacker deposit a second time during the payout, leaving extra
        // funds stuck in c.
        assertTrue(n % 15 != 0 || address(c).balance == 10 ether);
    }
}

contract Attacker {
    C c;
    bool attacked;

    constructor(C _c) { c = _c; }

    function attack() external {
        address(c).call{value: 10 ether}("");
    }

    receive() external payable {
        if (!attacked) {
            attacked = true;
            address(c).call{value: 10 ether}("");
        }
    }
}
